import csv

# Load data from CSV files
def load_csv(file_path):
    with open(file_path, mode='r', newline='', encoding='utf-8') as file:
        reader = csv.DictReader(file)
        return list(reader)

metadata_tables = load_csv('inputs/eurostat/metadata_tables.csv')
indicator_descriptions = load_csv('inputs/eurostat/indicator_descriptions.csv')

# Filter indicators by relevant themes
relevant_themes = {
    'mobility': ['transport', 'mobility'],
    'population_density': ['population', 'density'],
    'environment': ['environment'],
    'living_conditions': ['living', 'conditions']
}

selected_indicators = []

def theme_match(theme, keywords):
    return any(keyword in theme.lower() for keyword in keywords)

for description in indicator_descriptions:
    for table in metadata_tables:
        if description['indicator_id'] == table['indicator_id']:
            theme = table['theme']
            for theme_name, keywords in relevant_themes.items():
                if theme_match(theme, keywords):
                    indicator_name = description['indicator_name']
                    justification = f"Relevant to {theme_name}"
                    expected_direction = 'contextual'  # Default value, adjust as needed

                    # Determine expected direction based on theme
                    if theme_name == 'mobility':
                        expected_direction = 'higher_is_better'
                    elif theme_name == 'population_density':
                        expected_direction = 'contextual'
                    elif theme_name == 'environment':
                        expected_direction = 'lower_is_better'
                    elif theme_name == 'living_conditions':
                        expected_direction = 'higher_is_better'

                    selected_indicators.append({
                        'indicator_id': description['indicator_id'],
                        'indicator_name': indicator_name,
                        'theme': theme_name,
                        'justification': justification,
                        'expected_direction': expected_direction
                    })

# Limit the number of selected indicators to 10-15
selected_indicators = selected_indicators[:15]

# Write the selected indicators to the output CSV
output_columns = ['indicator_id', 'indicator_name', 'theme', 'justification', 'expected_direction']
output_path = 'outputs/t01_selected_indicators.csv'

with open(output_path, mode='w', newline='', encoding='utf-8') as file:
    writer = csv.DictWriter(file, fieldnames=output_columns, quoting=csv.QUOTE_NONNUMERIC)
    writer.writeheader()
    writer.writerows(selected_indicators)
